/// Directional key light for the unbaked bodies. There is no IBL in a full immersive space,
/// so without this a UsdPreviewSurface body renders black.
///
/// Placed up and to the LEFT and slightly on the viewer's side of the body, which puts the
/// terminator down the right-hand limb — the same handedness as the Blender previews, so a
/// body doesn't appear to flip its lighting between the contact sheet and the headset.
private static func makeSun(target: SIMD3<Float>) -> Entity {
    let sun = DirectionalLight()
    sun.name = sunName
    // Bright: these are albedo maps of sunlit bodies, and the surround is pure black, so an
    // interior-lighting default reads as dusk.
    sun.light.intensity = 3000
    sun.light.color = .white
    sun.shadow = nil    // one convex body, nothing to receive a shadow it doesn't already own
    // `look` aims the entity's -Z (a DirectionalLight's emission direction) at `target`.
    sun.look(at: target,
             from: target + normalize(SIMD3<Float>(-1.0, 0.45, 0.55)) * distance,
             relativeTo: nil)
    return sun
}

